   112|/** Aggregate every subsystem into one dashboard. Read-only; never mutates. */
   113|export async function buildAutonomousDashboard(): Promise<AutonomousDashboard> {
   114|  const [auditJobs, auditItemSets, codeIndex, codeGraph, continuous, priority] = await Promise.all([
   115|    listAuditJobs(100),
   116|    listAuditItemSets(100),
   117|    getCodeIndexSummary(),
   118|    getCodeGraphSummary(),
   119|    getContinuousSession(),
   120|    getPrioritySummary(),
   121|  ]);
   122|  const repairJobs = listRepairJobs(100);
   123|  const incidents = listIncidents(100);
   124|
   125|  const buckets = emptyBuckets();
   126|
   127|  // Audit jobs → buckets.
   128|  for (const job of auditJobs) {
   129|    buckets[auditJobToBucket(job)] += 1;
   130|  }
   131|
   132|  // Structured audit items → buckets (the richest signal of real work).
   133|  let totalItems = 0;
   134|  for (const set of auditItemSets) {
   135|    const counts = countByStatus(set);
   136|    totalItems += set.items.length;
   137|    for (const status of Object.keys(counts) as AuditItemStatus[]) {
   138|      const bucket = auditItemStatusToBucket(status);
   139|      if (bucket) {
   140|        addBuckets(buckets, { [bucket]: counts[status] });
   141|      }
   142|    }
   143|  }
   144|
   145|  // Repair jobs → buckets.
   146|  let repairFailed = 0;
   147|  let repairAwaiting = 0;
   148|  for (const job of repairJobs) {
   149|    if (job.stage === 'failed') {
   150|      buckets.failed += 1;
   151|      repairFailed += 1;
   152|    } else if (job.stage === 'completed' || job.stage === 'auto_applied') {
   153|      buckets.completed += 1;
   154|    } else if (job.stage === 'awaiting_approval') {
   155|      buckets.blocked += 1;
   156|      repairAwaiting += 1;
   157|    } else if (job.stage === 'rollback_required') {
   158|      buckets.failed += 1;
   159|    } else {
   160|      buckets.pending += 1;
   161|    }
   162|  }
   163|
   164|  const activeJobs = auditJobs.filter((job) => job.status === 'queued' || job.status === 'running').length;
   165|  const completedJobs = auditJobs.filter((job) => job.status === 'completed').length;
   166|  const failedJobs = auditJobs.filter((job) => job.status === 'failed').length;
   167|  const openIncidents = incidents.filter((incident) => incident.status === 'open' || incident.status === 'diagnosing').length;
   168|  const resolvedIncidents = incidents.filter((incident) => incident.status === 'resolved').length;
   169|
   170|  // DEF-fix: databaseConfigured previously only checked for a direct Postgres connection
   171|  // string (DATABASE_URL / POSTGRES_URL / SUPABASE_DB_URL), which are NOT set on the Render
   172|  // runtime. The backend persists durable state through the Supabase REST API using
   173|  // EXPO_PUBLIC_SUPABASE_URL + SUPABASE_SERVICE_ROLE_KEY (service-role). Recognize that
   174|  // configuration as a valid, configured database so the dashboard reports `online` and
   175|  // `databaseConfigured: true` instead of a false `partial` / `false`.
   176|  const databaseConfigured = Boolean(
   177|    readEnvFlag('DATABASE_URL')
   178|    || readEnvFlag('POSTGRES_URL')
   179|    || readEnvFlag('SUPABASE_DB_URL')
   180|    || (readEnvFlag('EXPO_PUBLIC_SUPABASE_URL') && (readEnvFlag('SUPABASE_SERVICE_ROLE_KEY') || readEnvFlag('SUPABASE_SERVICE_KEY'))),
   181|  );
   182|  const githubConfigured = readEnvFlag('GITHUB_TOKEN') && readEnvFlag('GITHUB_REPO_URL');
   183|  const mode: 'production' | 'development' = process.env.NODE_ENV === 'production' ? 'production' : 'development';
