{"command":"python3 - <<'PY'
import json, urllib.request, urllib.error, time
base='https://api.ivxholding.com'
checks=[
 ('public_chat','POST','/api/public/chat',{'message':'What is 2 plus 3?'}),
 ('owner_ai_no_auth','POST','/api/ivx/owner-ai',{'message':'What is 2 plus 3?'}),
 ('owner_status_no_auth','GET','/api/ivx/owner-ai/status',None),
 ('autonomous_qa','GET','/api/ivx/autonomous/qa',None),
 ('autonomous_ledger','GET','/api/ivx/autonomous/ledger',None),
 ('autonomous_runs','GET','/api/ivx/autonomous/runs',None),
 ('autonomous_summary','GET','/api/ivx/autonomous/runs/summary',None),
 ('executive_layer','GET','/api/ivx/executive-layer',None),
]
for name,method,path,payload in checks:
  data=json.dumps(payload).encode() if payload else None
  req=urllib.request.Request(base+path,data=data,method=method,headers={'Content-Type':'application/json'} if data else {})
  start=time.time()
  try:
    with urllib.request.urlopen(req,timeout=20) as r:
      raw=r.read().decode(); code=r.status
  except urllib.error.HTTPError as e:
    code=e.code; raw=e.read().decode()
  except Exception as e:
    print(name,'ERROR',str(e)); continue
  try: body=json.loads(raw)
  except: body={'raw':raw[:200]}
  safe={k:body.get(k) for k in ('ok','status','error','message','provider','model','commit','total','count','marker') if k in body}
  print(name,'HTTP',code,'ms',round((time.time()-start)*1000),'body',safe)
